let c_limit = 60; // shut down test if either temp exceeds
let charge_temp = 40; // lower charge power if either probe exceeds this
let idle_charge = 24; // grid watts when idling in auto off (~5-6 amps)

function updateBatteryWatts(measuredAmps, targetAmps, currentWatts,
                            measuredVolts, targetVolts) {
    // --- Tuning ---
    const Kp = 5;             // was 8  -- gentler P response to overshoots
    const Ki = 1;             // was 2  -- slower integral wind-up
    // CC: ignore wobble inside ±2.5A. With 60s amp samples already feeding in,
    // trying to correct anything tighter just chases noise the inverter has
    // already partly absorbed.
    const deadband = 2.5;     // was 1.0
    // Smaller minimum kick. Combined with the wider deadband, we react less
    // often, and when we do, we don't slam the actuator with a 10W step that
    // the lag turns into a 3-4A swing.
    const minDelta = 5;       // was 10
    const maxDelta = 50;      // unchanged -- still allow fast CV cuts
    const wattsMin = -2000;
    const wattsMax =  2000;
    // CV regulation: tight taper. At taperBand=0.15, dropping 0.10V past target
    // cuts the amps target by 67%. Fully zero at 0.15V past. This is what gives
    // you "voltage doesn't keep dropping past 12" -- the loop slams amps toward
    // zero very fast as soon as the target is crossed.
    const taperBand = 0.15;   // was 0.5
    // Longer settle: at the 1Hz call rate, this means we update only every
    // ~4 ticks. Each correction has time to actually land before the next is
    // computed, so we stop stacking commands the system hasn't responded to.
    const settleSeconds = 4;  // was 2

    // --- Persistent state ---
    let lastError = context.get('pid_lastError');
    if (lastError === undefined) lastError = 0;
    let lastTarget = context.get('pid_lastTarget');
    if (lastTarget === undefined) lastTarget = targetAmps;
    let lastUpdate = context.get('pid_lastUpdate');
    if (lastUpdate === undefined) lastUpdate = 0;

    const now = Date.now();
    const dtSinceUpdate = (now - lastUpdate) / 1000;

    // --- Rate limit: hold output if we adjusted recently. We don't even
    //     compute the PI math during the hold -- this guarantees the
    //     velocity-form (error - lastError) term operates on the change
    //     between actual UPDATES, not between every tick, which keeps it
    //     honest when the system is laggy. ---
    if (dtSinceUpdate < settleSeconds) {
        return Math.round(currentWatts);
    }

    // dt is now the time between updates, not between calls. Used by the
    // integral term so it accumulates at the right rate regardless of how
    // often the function is invoked.
    const dt = Math.min(10, Math.max(0.1, dtSinceUpdate));

    // --- Voltage-conditioned amp target.
    //     "overshoot" = how far PAST the limit we've gone (positive = past).
    //     Charging:    overshoot > 0 when V is above the upper cutoff.
    //     Discharging: overshoot > 0 when V is below the lower floor.
    //     Until overshoot crosses zero we hold full commanded amps. After,
    //     we taper linearly to zero over taperBand volts. This is the
    //     CC-until-target-then-CV behavior you wanted -- voltage variations
    //     that don't cross the target have NO effect on the amps target,
    //     so the test runs at full discharge rate until the floor is hit. ---
    const overshoot = (targetAmps >= 0)
        ? measuredVolts - targetVolts
        : targetVolts - measuredVolts;

    let taperFactor;
    if (overshoot <= 0) {
        taperFactor = 1.0;                            // not past target: full CC
    } else if (overshoot >= taperBand) {
        taperFactor = 0;                              // way past: hold at zero
    } else {
        taperFactor = 1.0 - (overshoot / taperBand); // tapering CC -> CV
    }
    const effectiveAmpTarget = targetAmps * taperFactor;

    const error = effectiveAmpTarget - measuredAmps;

    // --- Mode flip: zero P-term kick on charge<->discharge transitions ---
    const modeFlipped = lastTarget !== 0 && targetAmps !== 0
                        && Math.sign(targetAmps) !== Math.sign(lastTarget);
    const errorForDelta = modeFlipped ? error : lastError;

    // --- Velocity PI ---
    let deltaWatts;
    if (Math.abs(error) < deadband) {
        deltaWatts = 0;
    } else {
        deltaWatts = Kp * (error - errorForDelta) + Ki * error * dt;
    }

    // --- Force minimum effective change to overcome actuator hysteresis.
    //     If the math says move, make sure we move by enough that the
    //     inverter actually responds. Without this, a small delta computed
    //     when error is barely past the deadband gets absorbed silently and
    //     the loop never escapes. The deadband above prevents this from
    //     turning into ringing -- inside it we don't move at all. ---
    if (deltaWatts > 0 && deltaWatts < minDelta) deltaWatts = minDelta;
    if (deltaWatts < 0 && deltaWatts > -minDelta) deltaWatts = -minDelta;

    // Clamp absolute slew, then output range.
    if (deltaWatts >  maxDelta) deltaWatts =  maxDelta;
    if (deltaWatts < -maxDelta) deltaWatts = -maxDelta;

    let newWatts = currentWatts + deltaWatts;
    if (newWatts > wattsMax) newWatts = wattsMax;
    if (newWatts < wattsMin) newWatts = wattsMin;

    // --- Save state. Note pid_lastTime is replaced by pid_lastUpdate --
    //     we only update state when we actually change watts, so the
    //     velocity PI math sees the deltas between real updates. ---
    context.set('pid_lastError',  error);
    context.set('pid_lastTarget', targetAmps);
    context.set('pid_lastUpdate', now);

    newWatts = Math.round(newWatts);
    return newWatts;
}


let start = context.get('start') || 0;
if (start == 0) {
    start = Date.now();
    context.set('start', start);
}
let elapsed = parseInt((Date.now() - start)/60000);

// store inbound values by topic for persistent reference
let avg_over = 30; // fake average for amps over x iterations
let store = context.get('store') || {};
store[msg.topic] = msg.payload;
if (msg.topic == 'amps') {
    let avg = store['avg'] || 0;
    avg = avg - avg/avg_over + msg.payload/avg_over;
    store['avg'] = parseFloat(avg.toFixed(2));
}
context.set("store", store)

function setGrid(value) {
    msg.topic='grid';
    msg.payload = value;
    store['grid'] = value;
    context.set("store", store);    
    return msg;
}

// grid is positive in charging mode, negative discharging, zero stopped
if ('grid' in store && 'amps' in store) {
    let grid = store['grid'];
    let amps = store['amps'];
    let avg = store['avg'];
    let ah = -store['ah'];
    let volts = store['volts'] || 14.666;
    let discharge_amps = store['Discharge Amps'] || 0;
    let charge_amps = store['Charge Amps'] || 0;
    let auto = store['Auto'] || 0;
    let cc = store['CC'] || 0;
    let target = 0;
    let m = grid/amps;
    m = parseFloat(m.toFixed(2));

    // check temps for limit
    if (grid != 0 && 'Positive' in store) {
        let c = store['Positive'];
        if (c>c_limit) {
            node.send({topic: 'auto', payload: 0});
            node.send({ type: 1, title: "Test Abort", payload: "Positive Terminal at "+c+"C " +amps+"A" });
            return setGrid(0);
        }
    }
    if (grid != 0 && 'Negative' in store) {
        let c = store['Negative'];
        if (c>c_limit) {
            node.send({topic: 'auto', payload: 0});
            node.send({ type: 1, title: "Test Abort", payload: "Negative Terminal at "+c+"C "+amps+"A" });
            return setGrid(0);
        }
    }

    if (grid > idle_charge) {
        target = charge_amps;
        node.status({text: "charging " + avg + " e="+elapsed + " t="+target+" m="+m});

        if (elapsed > 0 && avg < 1.50 && ah==0) {
            context.set('start', Date.now());
            node.send({ title: "Test Result", payload: "Charged to "+ah+" Ah at "+charge_amps+"A in "+elapsed+" mins" });
            if (auto && discharge_amps > 0) {
                return setGrid(-discharge_amps*11);
            }
            return setGrid(idle_charge);
        }
    } else if (grid < 0) {
        target = -discharge_amps;
        node.status({text: "discharging " + avg + " v="+volts+" e="+elapsed+" t="+target+" m="+m});

        if (elapsed > 0 && (amps > -1 || volts <11.8)) {
            context.set('start', Date.now());
            // track last 10 discharge Ah readings
            let history = context.get('discharge_history') || [];
            history.push(parseFloat(ah));
            while (history.length > 10) {
                history.shift();
            }
            context.set('discharge_history', history);
            let last5 = history.slice(-5);
            let avg5 = last5.reduce(function(a,b){return a+b;}, 0) / last5.length;
            let history_str = history.map(function(v){return v.toFixed(1);}).join(", ");
            node.send({ title: "Test Result", payload: "Discharged to "+ah.toFixed(1)+" Ah at "+discharge_amps+"A in "+elapsed+" mins, avg(5)="+avg5.toFixed(1)+" Ah, last 10: ["+history_str+"]" });
            if (charge_amps > 0) {
                return setGrid(charge_amps*15);
            }
            return msg;
        }
    } else {
        node.status({text: "idle " + avg + " ah="+ah});
        if (auto && charge_amps) {
            context.set('start', Date.now());
            node.send({ title: "Test Result", payload: "Starting test charge"});
            return setGrid(charge_amps*15);
        }
    }

    // tweak the grid watts to keep amps closer to target
    if (!target) return null;

    /*
    let last_change = context.get('change') || 0;
    let secs_since = parseInt((Date.now() - last_change)/1000);
    let tweak = 0;    
    let pc = store['Positive'] || 0;
    let nc = store['Negative'] || 0;
    if (amps>target && avg>target) {
        if (grid < 0 || grid > idle_charge) {
            tweak = -1;
        }
    }
    if (amps<target && avg<target && grid<20*charge_amps) {
        if (grid < -6 || grid > idle_charge)
            tweak = 1;
    }
    if (grid < -6 && volts < 12.1) {
        tweak = 1;
    }
    if (target > 0 && grid > 24) {
        // for agm batteries, don't overcharge to boiling
        if (pc > charge_temp || nc > charge_temp) {
            tweak = -1;
        }
    }
    if (!auto) return null;
    if (!tweak) return null;
    if (secs_since < 1) return null;
    if (elapsed == 0) return null;
    //node.status({text: "tweak " + tweak + " grid="+grid+ " seconds="+secs_since});
    context.set('change', Date.now())
    */
    // CC flag: hold full discharge current all the way down -- no CV taper
    // near the floor. The taper kept unloading the pack just above the 11.8V
    // completion trigger, so the discharge never "finished" and the capacity
    // email never went out. Passing a 0V floor means overshoot stays negative
    // and updateBatteryWatts regulates pure CC; completion fires on volts<11.8.
    newGrid = updateBatteryWatts(amps, target, grid, volts, grid<0 ? (cc ? 0.0 : 12.0) : 16.0);

    if (grid < 0 && newGrid >= 0) grid=-1;

    if (newGrid != grid)
    return setGrid(newGrid);
}
return null;
